/**
 * @file ev_powertrain.h
 * @brief Compiled zero-allocation Port-Hamiltonian model generated by RT-MPBC.
 * Standard: MISRA-C:2012 / C99 bare-metal compatible.
 */

#ifndef RTMPBC_COMPILED_EV_POWERTRAIN_H
#define RTMPBC_COMPILED_EV_POWERTRAIN_H

#include "rtmpbc.h"

#define EV_POWERTRAIN_N_STATES 4
#define EV_POWERTRAIN_N_INPUTS 0
#define EV_POWERTRAIN_INPUTS_DIM 1
#define EV_POWERTRAIN_DT 0.0001000000

/* State variable indexing */
#define EV_POWERTRAIN_STATE_C_BATTERY 0
#define EV_POWERTRAIN_STATE_I_ROTOR_INERTIA 1
#define EV_POWERTRAIN_STATE_C_SHAFT_TORSION 2
#define EV_POWERTRAIN_STATE_I_VEHICLE_MASS 3

/* Input port indexing */

typedef struct {
    rtmpbc_real_t x[EV_POWERTRAIN_N_STATES];
    rtmpbc_real_t u[EV_POWERTRAIN_INPUTS_DIM];
    rtmpbc_real_t y[EV_POWERTRAIN_INPUTS_DIM];
    rtmpbc_real_t total_energy;
} ev_powertrain_sim_t;

void ev_powertrain_init(ev_powertrain_sim_t* sim);
void ev_powertrain_step(ev_powertrain_sim_t* sim);
rtmpbc_real_t ev_powertrain_energy(const ev_powertrain_sim_t* sim);

#endif /* RTMPBC_COMPILED_EV_POWERTRAIN_H */
